const express = require('express');
const { Scalekit } = require('@scalekit-sdk/node');

const app = express();
const port = 3001;

// Initialize Scalekit client
// In a real application, these would be environment variables
const scalekit = new Scalekit(
  'https://your-env.scalekit.com',
  'your-client-id',
  'your-client-secret'
);

const authMiddleware = async (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }

  const token = authHeader.split(' ')[1];

  try {
    // Validate the token and check for required scopes
    await scalekit.validateToken(token, {
      requiredScopes: ['todo:read'],
    });
    next();
  } catch (error) {
    console.error('Token validation failed:', error.message);
    return res.status(403).json({ error: 'Invalid token or insufficient permissions' });
  }
};

app.get('/todos', authMiddleware, (req, res) => {
  const todos = [
    { id: 1, task: 'Learn Scalekit Middleware', completed: false },
    { id: 2, task: 'Secure API Endpoints', completed: true },
  ];
  res.json(todos);
});

app.listen(port, () => {
  console.log(`Server is running on http://localhost:${port}`);
});

